window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5898ccf7d68951d8"]={"versions": [{"id": "FIG-5898ccf7d68951d8", "releases": ["R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden- und Werkzeug-Interaktionsdiagramm im Kontext der AUTOSAR-Methodik (AUTOSAR_TR_InteractionWithBehavioralModels). Es visualisiert die Schnittstellen und Verantwortlichkeitsgrenzen zwischen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools), Kopplungswerkzeugen (Coupling Tools) und AUTOSAR-Autorenwerkzeugen (System Configuration Tools). Der rosafarbene Bereich definiert den normativen Geltungs- und Funktionsbereich von AUTOSAR-Autorenwerkzeugen („covered by AUTOSAR authoring tools“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Artefakte / Beschreibungsdokumente (blaues Dokumenten-Icon):</strong></li>\n<li><code>Behavioral Model</code>: Modellbasierte Verhaltensspezifikation (z. B. Simulink-, TargetLink- oder ASCET-Modell) außerhalb des AUTOSAR-Authoring-Bereichs.</li>\n<li><code>System Configuration Input :System</code> (.XML): ARXML-Eingangsartefakt der Systemkonfiguration, bestehend aus Software-Component-Descriptions (SW-C) und Systemvorgaben; agiert als Schnittstelle zur Verhaltensmodellierung.</li>\n<li><code>System Configuration Description : System</code> (.XML): Vollständige Systemkonfigurationsbeschreibung als primäres Ausgangsartefakt.</li>\n<li><strong>Aktivitäten / Prozessschritte (gelbe Blockpfeile/Chevrons):</strong></li>\n<li><code>Translation of SW-C Description into Behavioral Model</code>: Transformation von AUTOSAR-SW-C-Beschreibungen in ein proprietäres Verhaltensmodell.</li>\n<li><code>Translation of Behavioral Model into SW-C Description</code>: Rücküberführung modifizierter oder neu generierter SW-C-Beschreibungen aus dem Verhaltensmodell in das AUTOSAR-XML-Format.</li>\n<li><code>Configure System</code>: Systemkonfigurationsprozess zur Zuordnung von Komponenten zu Steuergeräten, Netzwerk- und Kommunikationsdesign.</li>\n<li><strong>Werkzeuge (gelbe Werkzeug-Piktogramme) & Annotationen:</strong></li>\n<li><code>Coupling Tool</code>: Werkzeug zur bidirektionalen Kopplung und Übersetzung zwischen Verhaltensmodell und ARXML-Beschreibungen (über gestrichelte Linien an beide Übersetzungsaktivitäten angebunden).</li>\n<li><code>AUTOSAR [Authoring Tool]</code>: Werkzeug zur Ausführung der Systemkonfiguration (gestrichelt an <code>Configure System</code> angebunden).</li>\n<li>Notizbox: Spezifiziert, dass die Aktivität <code>Configure System</code> innerhalb eines Autorenwerkzeugs manuell durchgeführt werden kann und das Werkzeug daher als manuelles Systemkonfigurationswerkzeug aufgefasst werden kann.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Export / Vorwärtsübersetzung:</strong> Aus dem vorhandenen <code>System Configuration Input :System</code> (.XML) werden SW-C-Beschreibungen über die Aktivität <code>Translation of SW-C Description into Behavioral Model</code> (geführt durch das <code>Coupling Tool</code>) in das <code>Behavioral Model</code> überführt.</li>\n<li><strong>Re-Import / Rückübersetzung:</strong> Nach Ausarbeitung oder Anpassung der Regelungs- und Funktionslogik im <code>Behavioral Model</code> werden die resultierenden Schnittstellen- und Verhaltensparameter über <code>Translation of Behavioral Model into SW-C Description</code> (ebenfalls via <code>Coupling Tool</code>) zurück in den <code>System Configuration Input :System</code> synchronisiert (Round-Trip-Engineering).</li>\n<li><strong>Systemkonfiguration:</strong> Der konsolidierte <code>System Configuration Input :System</code> wird der Aktivität <code>Configure System</code> zugeführt, die manuell oder teilautomatisiert durch ein AUTOSAR-Autorenwerkzeug ausgeführt wird.</li>\n<li><strong>Ergebnisgenerierung:</strong> <code>Configure System</code> erzeugt als Endstufe die <code>System Configuration Description : System</code> (.XML).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der dargestellte Ablauf ist ein technischer Leitfaden (Technical Report, TR) zur toolgestützten Integration von Modellierungsumgebungen in die AUTOSAR-Toolkette.</li>\n<li>AUTOSAR-Autorenwerkzeuge sind formal für die Konsistenz und Konformität der ARXML-Artefakte (<code>System Configuration Input</code> und <code>System Configuration Description</code>) gemäß AUTOSAR-Metamodell verantwortlich.</li>\n<li>Das <code>Coupling Tool</code> muss sicherstellen, dass bei bidirektionalen Übersetzungen semantische Verluste vermieden werden und keine Systemkonfigurationsdaten außerhalb des Komponentenverhaltens korrumpiert werden.</li>\n<li>Die Systemkonfiguration (<code>Configure System</code>) kann flexibel als manueller GUI-basierter Bearbeitungsschritt oder als automatisierter Algorithmus implementiert sein, muss jedoch stets eine valide <code>System Configuration Description</code> erzeugen.</li>\n</ul>"}, {"id": "FIG-15db3c357427a862", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden- und Werkzeug-Interaktionsdiagramm im Kontext der AUTOSAR-Methodik (AUTOSAR_TR_InteractionWithBehavioralModels). Es visualisiert die Schnittstellen und Verantwortlichkeitsgrenzen zwischen Verhaltensmodellierungswerkzeugen (Behavioral Modeling Tools), Kopplungswerkzeugen (Coupling Tools) und AUTOSAR-Autorenwerkzeugen (System Configuration Tools). Der rosafarbene Bereich definiert den normativen Geltungs- und Funktionsbereich von AUTOSAR-Autorenwerkzeugen („covered by AUTOSAR authoring tools“).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Artefakte / Beschreibungsdokumente (blaues Dokumenten-Icon):</strong></li>\n<li><code>Behavioral Model</code>: Modellbasierte Verhaltensspezifikation (z. B. Simulink-, TargetLink- oder ASCET-Modell) außerhalb des AUTOSAR-Authoring-Bereichs.</li>\n<li><code>System Configuration Input :System</code> (.XML): ARXML-Eingangsartefakt der Systemkonfiguration, bestehend aus Software-Component-Descriptions (SW-C) und Systemvorgaben; agiert als Schnittstelle zur Verhaltensmodellierung.</li>\n<li><code>System Configuration Description : System</code> (.XML): Vollständige Systemkonfigurationsbeschreibung als primäres Ausgangsartefakt.</li>\n<li><strong>Aktivitäten / Prozessschritte (gelbe Blockpfeile/Chevrons):</strong></li>\n<li><code>Translation of SW-C Description into Behavioral Model</code>: Transformation von AUTOSAR-SW-C-Beschreibungen in ein proprietäres Verhaltensmodell.</li>\n<li><code>Translation of Behavioral Model into SW-C Description</code>: Rücküberführung modifizierter oder neu generierter SW-C-Beschreibungen aus dem Verhaltensmodell in das AUTOSAR-XML-Format.</li>\n<li><code>Configure System</code>: Systemkonfigurationsprozess zur Zuordnung von Komponenten zu Steuergeräten, Netzwerk- und Kommunikationsdesign.</li>\n<li><strong>Werkzeuge (gelbe Werkzeug-Piktogramme) & Annotationen:</strong></li>\n<li><code>Coupling Tool</code>: Werkzeug zur bidirektionalen Kopplung und Übersetzung zwischen Verhaltensmodell und ARXML-Beschreibungen (über gestrichelte Linien an beide Übersetzungsaktivitäten angebunden).</li>\n<li><code>AUTOSAR [Authoring Tool]</code>: Werkzeug zur Ausführung der Systemkonfiguration (gestrichelt an <code>Configure System</code> angebunden).</li>\n<li>Notizbox: Spezifiziert, dass die Aktivität <code>Configure System</code> innerhalb eines Autorenwerkzeugs manuell durchgeführt werden kann und das Werkzeug daher als manuelles Systemkonfigurationswerkzeug aufgefasst werden kann.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Export / Vorwärtsübersetzung:</strong> Aus dem vorhandenen <code>System Configuration Input :System</code> (.XML) werden SW-C-Beschreibungen über die Aktivität <code>Translation of SW-C Description into Behavioral Model</code> (geführt durch das <code>Coupling Tool</code>) in das <code>Behavioral Model</code> überführt.</li>\n<li><strong>Re-Import / Rückübersetzung:</strong> Nach Ausarbeitung oder Anpassung der Regelungs- und Funktionslogik im <code>Behavioral Model</code> werden die resultierenden Schnittstellen- und Verhaltensparameter über <code>Translation of Behavioral Model into SW-C Description</code> (ebenfalls via <code>Coupling Tool</code>) zurück in den <code>System Configuration Input :System</code> synchronisiert (Round-Trip-Engineering).</li>\n<li><strong>Systemkonfiguration:</strong> Der konsolidierte <code>System Configuration Input :System</code> wird der Aktivität <code>Configure System</code> zugeführt, die manuell oder teilautomatisiert durch ein AUTOSAR-Autorenwerkzeug ausgeführt wird.</li>\n<li><strong>Ergebnisgenerierung:</strong> <code>Configure System</code> erzeugt als Endstufe die <code>System Configuration Description : System</code> (.XML).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der dargestellte Ablauf ist ein technischer Leitfaden (Technical Report, TR) zur toolgestützten Integration von Modellierungsumgebungen in die AUTOSAR-Toolkette.</li>\n<li>AUTOSAR-Autorenwerkzeuge sind formal für die Konsistenz und Konformität der ARXML-Artefakte (<code>System Configuration Input</code> und <code>System Configuration Description</code>) gemäß AUTOSAR-Metamodell verantwortlich.</li>\n<li>Das <code>Coupling Tool</code> muss sicherstellen, dass bei bidirektionalen Übersetzungen semantische Verluste vermieden werden und keine Systemkonfigurationsdaten außerhalb des Komponentenverhaltens korrumpiert werden.</li>\n<li>Die Systemkonfiguration (<code>Configure System</code>) kann flexibel als manueller GUI-basierter Bearbeitungsschritt oder als automatisierter Algorithmus implementiert sein, muss jedoch stets eine valide <code>System Configuration Description</code> erzeugen.</li>\n</ul>"}], "trans": [{"from": "FIG-5898ccf7d68951d8", "to": "FIG-15db3c357427a862", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
